  "fixed_code": "from .models import Order\nfrom typing import List, Dict, Any\n\ndef order_summaries(user: Any) -> List[Dict[str, Any]]:\n    \"\"\"Returns a list of dictionaries containing summary information for orders accessible by the user.\"\"\"\n    summaries = []\n    # Fixed N+1 query using select_related and added basic authorization filtering\n    for order in Order.objects.filter(user=user).select_related('customer'):\n        summaries.append({\n            \"id\": order.id,\n            \"customer\": order.customer.name,\n            \"total\": order.total,\n        })\n    return summaries"
